// Parse incoming params from the toolWorkflow caller.
// LLM may pass them as a JSON string in `query`, or as direct fields.
const raw = $input.first().json;
let action = '', task = '', url = '', domain = '', maxSteps = 25, timeoutS = 300;
try {
  const p = JSON.parse(raw.query || '{}');
  action = p.action || '';
  task = p.task || '';
  url = p.url || '';
  domain = p.domain || '';
  maxSteps = Number(p.max_steps) || 25;
  timeoutS = Number(p.timeout_s) || 300;
} catch(e) {
  action = raw.action || '';
  task = raw.task || '';
  url = raw.url || '';
  domain = raw.domain || '';
  maxSteps = Number(raw.max_steps) || 25;
  timeoutS = Number(raw.timeout_s) || 300;
}

// Chromium alone may need up to 120s to start, and that time counts against
// this budget. Agents kept passing 60 or 120 and the task died during startup.
timeoutS = Math.min(Math.max(timeoutS, 180), 900);

const userId = raw.userId || raw.user_id || 'telegram:{{TELEGRAM_CHAT_ID}}';
const BRIDGE = 'http://browser-bridge:3400';

function errorResponse(msg) {
  return [{ json: { success: false, error: msg } }];
}

if (!action) {
  return errorResponse('Parameter "action" is required. One of: task, list_sessions, close_session.');
}

// Schutz vor Leerlaeufen (Auswertung 03. bis 08.09.2026: drei Browserlaeufe, 161 s,
// kein Ergebnis): ohne konkreten Auftrag startet kein Browser, und Microsoft-Dienste
// gehen nicht, weil der Browser dort keine Anmeldung hat.
if (action === 'task') {
  const t = String(task || '').trim();
  const woerter = t.split(/\s+/).filter(Boolean).length;
  const zielSeite = String(url || '').trim() || String(domain || '').trim();
  // Zeichen zaehlen war zu grob ("Oeffne orf.at" ist ein gueltiger Auftrag): mindestens
  // drei Woerter, oder zwei Woerter, wenn Adresse oder Domain schon feststehen.
  if (woerter < (zielSeite ? 2 : 3) || /^(placeholder|platzhalter|test|todo|tbd)$/i.test(t)) {
    return errorResponse('Kein brauchbarer Auftrag: "' + t.slice(0, 40) + '". Der Browser startet nur mit einer konkreten Aufgabe (was soll auf welcher Seite passieren).');
  }
  // Nur Adresse und Domain pruefen, nicht den Fliesstext: "wie in Outlook." oder eine
  // Seite namens ski-live.com haben mit Microsoft nichts zu tun.
  const ziel = (String(url || '') + ' ' + String(domain || '')).toLowerCase();
  if (/(^|[\s\/@.])(microsoft\.com|microsoftonline\.com|sharepoint\.com|office\.com|live\.com|outlook\.(com|office|live)|teams\.microsoft\.com)([\s\/:?]|$)/i.test(ziel)) {
    return errorResponse('Microsoft-Dienste (Teams, SharePoint, Outlook, Anmeldung) gehen nicht ueber den Browser, dort gibt es keine Anmeldung fuer Rupert. Nutze die Microsoft-Werkzeuge (Kalender, Postfach, SharePoint, Teams-Bote).');
  }
  // Atlassian ebenso (10.09.2026): acht Browser-Aufrufe auf eine Confluence-Seite endeten
  // alle an der Login-Wand. Confluence und Jira haben eigene Werkzeuge.
  if (/(^|[\s\/@.])([a-z0-9-]+\.atlassian\.net|atlassian\.com|id\.atlassian\.com|atl-paas\.net)([\s\/:?]|$)/i.test(ziel) || /\b(confluence|jira)\b/i.test(zielSeite)) {
    return errorResponse('Confluence und Jira gehen nicht ueber den Browser, dort gibt es keine Anmeldung fuer Rupert. Nutze die Confluence-Werkzeuge (get_page, search_pages, update_page, append_to_page) oder die Jira-Werkzeuge.');
  }
}

if (action === 'task') {
  if (!task) return errorResponse('Parameter "task" is required for action=task.');
  try {
    const res = await helpers.httpRequest({
      method: 'POST',
      url: `${BRIDGE}/tasks`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        user_id: userId,
        task,
        url: url || null,
        domain: domain || null,
        max_steps: maxSteps,
        timeout_s: timeoutS,
      },
      json: true,
      timeout: (timeoutS + 30) * 1000,
    });
    return [{ json: { success: res.status === 'completed', ...res } }];
  } catch(e) {
    return errorResponse(`Browser task failed: ${e.message}`);
  }
}

if (action === 'list_sessions') {
  try {
    const res = await helpers.httpRequest({
      method: 'GET',
      url: `${BRIDGE}/sessions/${encodeURIComponent(userId)}`,
      json: true,
      timeout: 10000,
    });
    const sessions = res.sessions || [];
    if (sessions.length === 0) {
      return [{ json: { success: true, sessions: [], message: 'No active browser sessions.' } }];
    }
    const lines = sessions.map(s => {
      const ageMin = Math.round((Date.now() / 1000 - s.last_used_at) / 60);
      return `- ${s.domain} (idle ${ageMin}m, ${s.n_tasks} tasks)`;
    });
    return [{ json: { success: true, sessions, message: `Active browser sessions:\n${lines.join('\n')}` } }];
  } catch(e) {
    return errorResponse(`Could not list sessions: ${e.message}`);
  }
}

if (action === 'close_session') {
  if (!domain) return errorResponse('Parameter "domain" is required for action=close_session.');
  try {
    const res = await helpers.httpRequest({
      method: 'DELETE',
      url: `${BRIDGE}/sessions/${encodeURIComponent(userId)}/${encodeURIComponent(domain)}`,
      json: true,
      timeout: 10000,
    });
    return [{ json: { success: true, ...res, message: `Browser session for ${domain} closed.` } }];
  } catch(e) {
    if (e.message && e.message.includes('404')) {
      return errorResponse(`No active session for domain "${domain}".`);
    }
    return errorResponse(`Could not close session: ${e.message}`);
  }
}

return errorResponse(`Unknown action "${action}". Use: task, list_sessions, close_session.`);
